mapper.select:
SELECT account_no, owner_id, owner_type, required_amount, balance, frozen_amount,
       balance - frozen_amount AS available_amount, status
FROM t_deposit_account WHERE account_no = #{accountNo}

mapper.update:
UPDATE t_deposit_account
SET balance = #{balance}, frozen_amount = #{frozenAmount}, updated_at = CURRENT_TIMESTAMP
WHERE account_no = #{accountNo}
  AND balance = #{expectedBalance}
  AND frozen_amount = #{expectedFrozenAmount}
  AND #{balance} >= #{frozenAmount}
  AND #{frozenAmount} >= 0
